CREATE TABLE public.video_credit_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,delta integer NOT NULL CHECK(delta<>0),reason text NOT NULL CHECK(reason IN ('pack_grant','debit','refund_failed')),related_entity_type text,related_entity_id uuid,attempt_id uuid,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
GRANT SELECT ON public.video_credit_ledger TO authenticated;
GRANT SELECT,INSERT ON public.video_credit_ledger TO service_role;
ALTER TABLE public.video_credit_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads video balance" ON public.video_credit_ledger FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.video_ledger_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Video ledger is append-only'; END $$;
CREATE TRIGGER video_ledger_immutable BEFORE UPDATE OR DELETE ON public.video_credit_ledger FOR EACH ROW EXECUTE FUNCTION public.video_ledger_append_only();
CREATE FUNCTION public.video_credit_balance(p_user uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(sum(delta),0)::integer FROM public.video_credit_ledger WHERE user_id=p_user AND (auth.uid()=p_user OR auth.role()='service_role'); $$;
REVOKE ALL ON FUNCTION public.video_credit_balance(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.video_credit_balance(uuid) TO authenticated,service_role;
CREATE FUNCTION public.debit_video_credits(p_user uuid,p_amount integer,p_kind text,p_entity uuid,p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE balance integer; k text:=p_kind||':'||p_entity::text||':'||p_attempt::text; existing integer; BEGIN
IF p_amount<0 OR p_kind IS NULL OR p_entity IS NULL OR p_attempt IS NULL THEN RAISE EXCEPTION 'Invalid video debit'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('video:'||p_user::text,0));
SELECT -delta INTO existing FROM public.video_credit_ledger WHERE user_id=p_user AND idempotency_key='debit:'||k;
SELECT COALESCE(sum(delta),0)::integer INTO balance FROM public.video_credit_ledger WHERE user_id=p_user;
IF existing IS NOT NULL THEN IF existing<>p_amount THEN RAISE EXCEPTION 'Video debit changed'; END IF; RETURN jsonb_build_object('ok',true,'existing',true,'balance',balance); END IF;
IF balance<p_amount THEN RETURN jsonb_build_object('ok',false,'balance',balance,'required',p_amount); END IF;
IF p_amount>0 THEN INSERT INTO public.video_credit_ledger(user_id,delta,reason,related_entity_type,related_entity_id,attempt_id,idempotency_key) VALUES(p_user,-p_amount,'debit',p_kind,p_entity,p_attempt,'debit:'||k); END IF;
RETURN jsonb_build_object('ok',true,'balance',balance-p_amount); END $$;
CREATE FUNCTION public.refund_video_credits(p_user uuid,p_kind text,p_entity uuid,p_attempt uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE amount integer; k text:=p_kind||':'||p_entity::text||':'||p_attempt::text; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('video:'||p_user::text,0));
IF EXISTS(SELECT 1 FROM public.video_credit_ledger WHERE user_id=p_user AND idempotency_key='refund:'||k) THEN RETURN jsonb_build_object('ok',false,'already_refunded',true); END IF;
SELECT -delta INTO amount FROM public.video_credit_ledger WHERE user_id=p_user AND idempotency_key='debit:'||k;
IF amount IS NULL THEN RETURN jsonb_build_object('ok',false,'no_debit',true); END IF;
INSERT INTO public.video_credit_ledger(user_id,delta,reason,related_entity_type,related_entity_id,attempt_id,idempotency_key) VALUES(p_user,amount,'refund_failed',p_kind,p_entity,p_attempt,'refund:'||k);
RETURN jsonb_build_object('ok',true,'amount',amount); END $$;
CREATE FUNCTION public.grant_video_credits(p_user uuid,p_amount integer,p_purchase_key text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_amount<=0 OR length(p_purchase_key)<1 THEN RAISE EXCEPTION 'Invalid video grant'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('video:'||p_user::text,0)); INSERT INTO public.video_credit_ledger(user_id,delta,reason,idempotency_key) VALUES(p_user,p_amount,'pack_grant','pack:'||p_purchase_key) ON CONFLICT(user_id,idempotency_key) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.debit_video_credits(uuid,integer,text,uuid,uuid),public.refund_video_credits(uuid,text,uuid,uuid),public.grant_video_credits(uuid,integer,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.debit_video_credits(uuid,integer,text,uuid,uuid),public.refund_video_credits(uuid,text,uuid,uuid),public.grant_video_credits(uuid,integer,text) TO service_role;
ALTER TABLE public.scene_attempts ADD COLUMN billing_balance text NOT NULL DEFAULT 'plan' CHECK(billing_balance IN ('plan','video'));
ALTER TABLE public.assembly_jobs ADD COLUMN billing_balance text NOT NULL DEFAULT 'plan' CHECK(billing_balance IN ('plan','video'));
DO $$ DECLARE f text; BEGIN
f:=pg_get_functiondef('public.claim_inspiration_attempt(uuid,uuid,uuid,text,text,integer,numeric,uuid[])'::regprocedure);
f:=replace(f,'reference_ids,lease_until) VALUES','reference_ids,lease_until,billing_balance) VALUES');
f:=replace(f,$s$p_references,now()+interval '5 minutes')$s$,$s$p_references,now()+interval '5 minutes',CASE WHEN p_operation='animate' THEN 'video' ELSE 'plan' END)$s$);
f:=replace(f,$s$d:=public.debit_credits(p_user,p_billed,'debit_image','inspiration_attempt',a.id,a.id);$s$,$s$IF p_operation='animate' THEN d:=public.debit_video_credits(p_user,p_billed,'inspiration_attempt',a.id,a.id); ELSE d:=public.debit_credits(p_user,p_billed,'debit_image','inspiration_attempt',a.id,a.id); END IF;$s$);
EXECUTE f;
f:=pg_get_functiondef('public.claim_assembly_job(uuid,uuid,uuid,jsonb,jsonb,integer,numeric,text)'::regprocedure);
f:=replace(f,'duration_seconds,lease_until) VALUES','duration_seconds,lease_until,billing_balance) VALUES');
f:=replace(f,$s$seconds,now()+interval '5 minutes')$s$,$s$seconds,now()+interval '5 minutes','video')$s$);
f:=replace(f,$s$public.debit_credits(p_user,p_billed,'debit_video','assembly',j.id,j.id)$s$,$s$public.debit_video_credits(p_user,p_billed,'assembly',j.id,j.id)$s$);
f:=replace(f,'Insufficient credits:','Insufficient video credits:'); EXECUTE f;
f:=pg_get_functiondef('public.fail_inspiration_attempt(uuid,text)'::regprocedure);
f:=replace(f,$s$IF a.billed>0 AND$s$,$s$IF a.billing_balance='video' THEN PERFORM public.refund_video_credits(a.user_id,'inspiration_attempt',a.id,a.id); ELSE IF a.billed>0 AND$s$);
f:=replace(f,'UPDATE public.scene_attempts SET status=','END IF; UPDATE public.scene_attempts SET status='); EXECUTE f;
f:=pg_get_functiondef('public.fail_assembly_job(uuid,text)'::regprocedure);
f:=replace(f,$s$IF j.billed>0 AND$s$,$s$IF j.billing_balance='video' THEN PERFORM public.refund_video_credits(j.user_id,'assembly',j.id,j.id); ELSE IF j.billed>0 AND$s$);
f:=replace(f,'UPDATE public.assembly_jobs SET status=','END IF; UPDATE public.assembly_jobs SET status='); EXECUTE f;
END $$;